// Python repr(float) formatting, plus PyYAML's represent_float post-processing.
// No JSON, no RegExp anywhere in this project.

// Shortest round-trip digits of |x| in the form 0.digits * 10^decpt.
function shortestDigits(x) {
  // Number.prototype.toExponential() with no argument yields the shortest
  // mantissa that uniquely identifies the double, e.g. "1.5e-7" or "3e8".
  const s = x.toExponential();
  const epos = s.indexOf('e');
  const mant = s.slice(0, epos);
  const exp = parseInt(s.slice(epos + 1), 10);
  let digits = '';
  for (const ch of mant) {
    if (ch !== '.') digits += ch;
  }
  // Strip any trailing zeros (defensive; shortest form should not have any).
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end--;
  digits = digits.slice(0, end);
  return { digits, decpt: exp + 1 };
}

// CPython float_repr_style 'short' formatting of a finite float.
export function pyReprFloat(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';
  const neg = x < 0;
  const { digits, decpt } = shortestDigits(Math.abs(x));
  let out;
  if (decpt > 16 || decpt <= -4) {
    // Exponential notation: d[.ddd]e±XX (exponent at least two digits).
    let m = digits[0];
    if (digits.length > 1) m += '.' + digits.slice(1);
    const e = decpt - 1;
    const esign = e < 0 ? '-' : '+';
    let eabs = String(Math.abs(e));
    if (eabs.length < 2) eabs = '0' + eabs;
    out = m + 'e' + esign + eabs;
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return neg ? '-' + out : out;
}

// PyYAML SafeRepresenter.represent_float value.
export function yamlFloatValue(x) {
  if (Number.isNaN(x)) return '.nan';
  if (x === Infinity) return '.inf';
  if (x === -Infinity) return '-.inf';
  let value = pyReprFloat(x).toLowerCase();
  if (!value.includes('.') && value.includes('e')) {
    const i = value.indexOf('e');
    value = value.slice(0, i) + '.0' + value.slice(i);
  }
  return value;
}

// datetime.date / datetime.datetime stand-ins matching CPython str()/isoformat()
// output as used by PyYAML's represent_date / represent_datetime.

function pad(n, w) {
  let s = String(n);
  while (s.length < w) s = '0' + s;
  return s;
}

export class YamlDate {
  constructor(year, month, day) {
    this.year = year; this.month = month; this.day = day;
  }
  isoformat() {
    return pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2);
  }
}

export class YamlDateTime {
  // tzOffset: minutes east of UTC, or null for naive.
  constructor(year, month, day, hour, minute, second, microsecond, tzOffset) {
    this.year = year; this.month = month; this.day = day;
    this.hour = hour; this.minute = minute; this.second = second;
    this.microsecond = microsecond; this.tzOffset = tzOffset;
  }
  isoformat(sep) {
    let s = pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2)
      + sep + pad(this.hour, 2) + ':' + pad(this.minute, 2) + ':' + pad(this.second, 2);
    if (this.microsecond !== 0) s += '.' + pad(this.microsecond, 6);
    if (this.tzOffset !== null) {
      const off = this.tzOffset;
      const sign = off < 0 ? '-' : '+';
      const a = Math.abs(off);
      s += sign + pad(Math.floor(a / 60), 2) + ':' + pad(a % 60, 2);
    }
    return s;
  }
  // UTC instant in microseconds (only meaningful when tzOffset !== null).
  utcMicros() {
    const days = daysFromCivil(this.year, this.month, this.day);
    return ((days * 24 + this.hour) * 60 + this.minute - this.tzOffset) * 60000000
      + this.second * 1000000 + this.microsecond;
  }
}

// Howard Hinnant's days_from_civil.
function daysFromCivil(y, m, d) {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

// Python equality between two keys of date/datetime type (other types handled
// elsewhere). Returns true/false.
export function timeEquals(a, b) {
  const aDate = a instanceof YamlDate;
  const bDate = b instanceof YamlDate;
  const aDt = a instanceof YamlDateTime;
  const bDt = b instanceof YamlDateTime;
  if (aDate && bDate) {
    return a.year === b.year && a.month === b.month && a.day === b.day;
  }
  if (aDt && bDt) {
    const aAware = a.tzOffset !== null;
    const bAware = b.tzOffset !== null;
    if (aAware && bAware) return a.utcMicros() === b.utcMicros();
    if (aAware !== bAware) return false; // naive == aware is False in Python
    return a.year === b.year && a.month === b.month && a.day === b.day
      && a.hour === b.hour && a.minute === b.minute && a.second === b.second
      && a.microsecond === b.microsecond;
  }
  return false; // date never equals datetime
}

// Python ordering comparison between date/datetime keys.
// Throws a TypeError-like Error when Python would raise TypeError.
export function timeCompare(a, b) {
  const aDate = a instanceof YamlDate;
  const bDate = b instanceof YamlDate;
  const aDt = a instanceof YamlDateTime;
  const bDt = b instanceof YamlDateTime;
  if (aDate && bDate) {
    return cmpNum(a.year, b.year) || cmpNum(a.month, b.month) || cmpNum(a.day, b.day);
  }
  if (aDt && bDt) {
    const aAware = a.tzOffset !== null;
    const bAware = b.tzOffset !== null;
    if (aAware !== bAware) {
      throw new Error("TypeError: can't compare offset-naive and offset-aware datetimes");
    }
    if (aAware) return cmpNum(a.utcMicros(), b.utcMicros());
    return cmpNum(a.year, b.year) || cmpNum(a.month, b.month) || cmpNum(a.day, b.day)
      || cmpNum(a.hour, b.hour) || cmpNum(a.minute, b.minute) || cmpNum(a.second, b.second)
      || cmpNum(a.microsecond, b.microsecond);
  }
  throw new Error("TypeError: can't compare datetime.datetime to datetime.date");
}

function cmpNum(a, b) { return a < b ? -1 : a > b ? 1 : 0; }

// Python dict semantics for constructed YAML mappings: insertion order,
// Python equality for keys (True == 1 == 1.0), hashability rules,
// and Python sorted() ordering for yaml.dump's represent_mapping.

import { YamlDate, YamlDateTime, timeEquals, timeCompare } from './pytime.mjs';

// A key is "numeric" in Python terms: bool, int (BigInt here), float (number).
function isNumericKey(v) {
  return typeof v === 'boolean' || typeof v === 'bigint' || typeof v === 'number';
}

// Compare numeric keys exactly; returns true/false for ==.
function numericEquals(a, b) {
  const na = toNumeric(a);
  const nb = toNumeric(b);
  if (na.kind === 'float' || nb.kind === 'float') {
    const fa = toFloat(na);
    const fb = toFloat(nb);
    if (Number.isNaN(fa) || Number.isNaN(fb)) return false;
    if (fa === Infinity || fa === -Infinity || fb === Infinity || fb === -Infinity) {
      return fa === fb;
    }
    // Exact comparison between BigInt and double.
    if (na.kind === 'bigint' && nb.kind === 'bigint') return na.value === nb.value;
    if (na.kind === 'bigint') return bigintEqualsFloat(na.value, fb);
    if (nb.kind === 'bigint') return bigintEqualsFloat(nb.value, fa);
    return fa === fb;
  }
  return na.value === nb.value;
}

function toNumeric(v) {
  if (typeof v === 'boolean') return { kind: 'bigint', value: v ? 1n : 0n };
  if (typeof v === 'bigint') return { kind: 'bigint', value: v };
  return { kind: 'float', value: v };
}

function toFloat(n) {
  return n.kind === 'bigint' ? bigintToFloat(n.value) : n.value;
}

function bigintToFloat(b) {
  // May lose precision for huge ints, only used for Infinity/NaN screening.
  return Number(b);
}

function bigintEqualsFloat(b, f) {
  if (!Number.isInteger(f)) return false;
  if (!Number.isFinite(f)) return false;
  // Safe: integers beyond 2^53 compare via exact BigInt conversion of the
  // double's exact mathematical value.
  return b === BigInt(f);
}

// Python == for YAML scalar keys.
export function pyKeyEquals(a, b) {
  if (isNumericKey(a) && isNumericKey(b)) return numericEquals(a, b);
  if (typeof a === 'string' || typeof b === 'string') return a === b;
  if (a === null || b === null) return a === b;
  if ((a instanceof YamlDate || a instanceof YamlDateTime)
      && (b instanceof YamlDate || b instanceof YamlDateTime)) {
    return timeEquals(a, b);
  }
  return false;
}

// Python hashability: lists/dicts are unhashable.
export function pyHashable(v) {
  return !(Array.isArray(v) || v instanceof PyMap);
}

// Ordered map with Python dict semantics.
export class PyMap {
  constructor() {
    this.pairs = []; // [key, value]
  }
  set(key, value) {
    for (const pair of this.pairs) {
      if (pyKeyEquals(pair[0], key)) {
        pair[1] = value;
        return;
      }
    }
    this.pairs.push([key, value]);
  }
  get size() { return this.pairs.length; }
}

// Python '<' between two sort keys. Throws Error('TypeError...') when Python
// would raise TypeError. NaN compares equal to everything (stable in place).
export function pyKeyCompare(a, b) {
  if (typeof a === 'string' && typeof b === 'string') {
    // Compare by code point (Python semantics), not UTF-16 units.
    const ca = Array.from(a);
    const cb = Array.from(b);
    const n = Math.min(ca.length, cb.length);
    for (let i = 0; i < n; i++) {
      const pa = ca[i].codePointAt(0);
      const pb = cb[i].codePointAt(0);
      if (pa !== pb) return pa < pb ? -1 : 1;
    }
    if (ca.length === cb.length) return 0;
    return ca.length < cb.length ? -1 : 1;
  }
  if (isNumericKey(a) && isNumericKey(b)) {
    const na = toNumeric(a);
    const nb = toNumeric(b);
    const fa = toFloat(na);
    const fb = toFloat(nb);
    if (Number.isNaN(fa) || Number.isNaN(fb)) return 0;
    if (na.kind === 'bigint' && nb.kind === 'bigint') {
      return na.value < nb.value ? -1 : na.value > nb.value ? 1 : 0;
    }
    if (na.kind === 'bigint') return bigintCompareFloat(na.value, fb);
    if (nb.kind === 'bigint') return -bigintCompareFloat(nb.value, fa);
    return fa < fb ? -1 : fa > fb ? 1 : 0;
  }
  if ((a instanceof YamlDate || a instanceof YamlDateTime)
      && (b instanceof YamlDate || b instanceof YamlDateTime)) {
    return timeCompare(a, b);
  }
  throw new Error('TypeError: unorderable types');
}

function bigintCompareFloat(b, f) {
  if (Number.isNaN(f)) return 0;
  if (f === Infinity) return -1;
  if (f === -Infinity) return 1;
  if (Number.isInteger(f)) {
    const fb = BigInt(f);
    return b < fb ? -1 : b > fb ? 1 : 0;
  }
  // Non-integral float: compare against floor/ceil.
  const ff = BigInt(Math.floor(f));
  if (b < ff) return -1;
  if (b > ff) return 1;
  return -1; // b == floor(f) < f
}

// PyYAML BaseRepresenter.represent_mapping sorts the item list with Python
// sorted(); on TypeError the original order is kept.
export function pySortPairs(pairs) {
  const copy = pairs.slice();
  try {
    copy.sort((pa, pb) => pyKeyCompare(pa[0], pb[0]));
    return copy;
  } catch (e) {
    if (e instanceof Error && e.message.startsWith('TypeError')) return pairs;
    throw e;
  }
}

// Minimal argparse emulation for: parser with one required option `--a`
// taking exactly one value. Matches CPython argparse exit codes:
//   0 on success, 2 on any CLI error (message to stderr), 0 for -h/--help.

function prog() {
  const p = process.argv[1] || 'test20.mjs';
  const parts = p.split('/');
  return parts[parts.length - 1];
}

function usage() {
  return 'usage: ' + prog() + ' [-h] --a A';
}

function errorExit(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(prog() + ': error: ' + message + '\n');
  process.exit(2);
}

function looksLikeOption(tok) {
  // argparse: a token starting with a prefix char is treated as an option
  // unless it is a negative number (parser has no number-like options) or it
  // is a single '-'.
  if (tok.length === 0 || tok[0] !== '-') return false;
  if (tok === '-') return false;
  if (isNegativeNumber(tok)) return false;
  return true;
}

function isNegativeNumber(tok) {
  // argparse's _negative_number_matcher: ^-\d+$|^-\d*\.\d+$
  if (tok[0] !== '-') return false;
  const s = tok.slice(1);
  if (s.length === 0) return false;
  if (allDigits(s)) return true;
  // -\d*\.\d+
  const dot = s.indexOf('.');
  if (dot === -1) return false;
  const intPart = s.slice(0, dot);
  const fracPart = s.slice(dot + 1);
  if (fracPart.length === 0) return false;
  if (intPart.length > 0 && !allDigits(intPart)) return false;
  return allDigits(fracPart);
}

function allDigits(s) {
  if (s.length === 0) return false;
  for (const ch of s) {
    if (ch < '0' || ch > '9') return false;
  }
  return true;
}

function printHelp() {
  let out = usage() + '\n\noptions:\n';
  out += '  -h, --help  show this help message and exit\n';
  out += '  --a A\n';
  process.stdout.write(out);
  process.exit(0);
}

// Returns the value of --a, or exits the process like argparse.
export function parseArgs(args) {
  let aValue = null;
  let aSeen = false;
  const extras = [];
  let i = 0;
  let noMoreOptions = false;
  while (i < args.length) {
    const tok = args[i];
    if (!noMoreOptions && tok === '--') {
      noMoreOptions = true;
      i++;
      continue;
    }
    if (!noMoreOptions && tok.startsWith('--')) {
      // Long option, possibly with =value; allow unambiguous abbreviations.
      let name = tok;
      let attached = null;
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        name = tok.slice(0, eq);
        attached = tok.slice(eq + 1);
      }
      const matches = [];
      for (const opt of ['--help', '--a']) {
        if (opt === name) { matches.length = 0; matches.push(opt); break; }
        if (opt.startsWith(name)) matches.push(opt);
      }
      if (matches.length === 1) {
        const opt = matches[0];
        if (opt === '--help') {
          if (attached !== null) errorExit('argument -h/--help: ignored explicit argument ' + squote(attached));
          printHelp();
        }
        // --a
        if (attached !== null) {
          aValue = attached;
          aSeen = true;
        } else {
          const next = i + 1 < args.length ? args[i + 1] : null;
          if (next === null || looksLikeOption(next)) {
            errorExit('argument --a: expected one argument');
          }
          aValue = next;
          aSeen = true;
          i++;
        }
      } else if (matches.length > 1) {
        errorExit('ambiguous option: ' + name + ' could match ' + matches.join(', '));
      } else {
        extras.push(tok);
      }
    } else if (!noMoreOptions && tok.length > 1 && tok[0] === '-' && !isNegativeNumber(tok)) {
      // Short option cluster.
      if (tok === '-h') {
        printHelp();
      }
      extras.push(tok);
    } else {
      extras.push(tok);
    }
    i++;
  }
  if (extras.length > 0) {
    errorExit('unrecognized arguments: ' + extras.join(' '));
  }
  if (!aSeen) {
    errorExit('the following arguments are required: --a');
  }
  return aValue;
}

function squote(s) { return "'" + s + "'"; }

// YAML node graph (composer output / representer output) and YAML errors.

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YAMLError';
  }
}

export class ScalarNode {
  constructor(tag, value, style = null) {
    this.kind = 'scalar';
    this.tag = tag;
    this.value = value;
    this.style = style;
  }
}

export class SequenceNode {
  constructor(tag, flowStyle = false) {
    this.kind = 'sequence';
    this.tag = tag;
    this.value = [];
    this.flowStyle = flowStyle;
  }
}

export class MappingNode {
  constructor(tag, flowStyle = false) {
    this.kind = 'mapping';
    this.tag = tag;
    this.value = []; // [[keyNode, valueNode], ...]
    this.flowStyle = flowStyle;
  }
}

// PyYAML SafeLoader implicit resolver (YAML 1.1 flavors), hand-coded
// without regular expressions.

export const TAG_STR = 'tag:yaml.org,2002:str';
export const TAG_NULL = 'tag:yaml.org,2002:null';
export const TAG_BOOL = 'tag:yaml.org,2002:bool';
export const TAG_INT = 'tag:yaml.org,2002:int';
export const TAG_FLOAT = 'tag:yaml.org,2002:float';
export const TAG_TIMESTAMP = 'tag:yaml.org,2002:timestamp';
export const TAG_MERGE = 'tag:yaml.org,2002:merge';
export const TAG_VALUE = 'tag:yaml.org,2002:value';
export const TAG_SEQ = 'tag:yaml.org,2002:seq';
export const TAG_MAP = 'tag:yaml.org,2002:map';

function isDigit(ch) { return ch >= '0' && ch <= '9'; }
function isDigitOrUnderscore(ch) { return isDigit(ch) || ch === '_'; }

function allMatch(s, from, pred) {
  if (from >= s.length) return false; // need at least one char
  for (let i = from; i < s.length; i++) {
    if (!pred(s[i])) return false;
  }
  return true;
}

// null: ~ | null | Null | NULL | (empty)
function matchNull(v) {
  return v === '' || v === '~' || v === 'null' || v === 'Null' || v === 'NULL';
}

const BOOL_VALUES = [
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
];

function matchBool(v) {
  return BOOL_VALUES.includes(v);
}

// int:
//   [-+]?0b[0-1_]+
//   [-+]?0[0-7_]+
//   [-+]?(0|[1-9][0-9_]*)
//   [-+]?0x[0-9a-fA-F_]+
//   [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+
function matchInt(v) {
  let s = v;
  if (s[0] === '+' || s[0] === '-') s = s.slice(1);
  if (s === '') return false;
  if (s.length > 2 && s[0] === '0' && s[1] === 'b') {
    return allMatch(s, 2, (c) => c === '0' || c === '1' || c === '_');
  }
  if (s.length > 2 && s[0] === '0' && s[1] === 'x') {
    return allMatch(s, 2, (c) => isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') || c === '_');
  }
  if (s.length > 1 && s[0] === '0'
      && allMatch(s, 1, (c) => (c >= '0' && c <= '7') || c === '_')) {
    return true;
  }
  if (s === '0') return true;
  if (s[0] >= '1' && s[0] <= '9' && allMatch(s, 1, isDigitOrUnderscore)) return true;
  // sexagesimal
  if (s[0] >= '1' && s[0] <= '9' && s.includes(':')) {
    const segs = s.split(':');
    if (segs.length < 2) return false;
    const first = segs[0];
    if (!(first[0] >= '1' && first[0] <= '9')) return false;
    if (!allMatch(first, 1, isDigitOrUnderscore) && first.length > 1) return false;
    for (let k = 1; k < segs.length; k++) {
      const g = segs[k];
      if (g.length === 1) {
        if (!isDigit(g[0])) return false;
      } else if (g.length === 2) {
        if (!(g[0] >= '0' && g[0] <= '5') || !isDigit(g[1])) return false;
      } else {
        return false;
      }
    }
    return true;
  }
  return false;
}

// float:
//   [-+]?[0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
//   \.[0-9][0-9_]*([eE][-+][0-9]+)?
//   [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
//   [-+]?\.(inf|Inf|INF)
//   \.(nan|NaN|NAN)
function matchFloat(v) {
  if (v === '.nan' || v === '.NaN' || v === '.NAN') return true;
  let s = v;
  if (s[0] === '+' || s[0] === '-') s = s.slice(1);
  if (s === '.inf' || s === '.Inf' || s === '.INF') return true;
  if (s === '') return false;
  // sexagesimal float
  if (s.includes(':')) {
    const dotParts = s.split('.');
    if (dotParts.length !== 2) return false;
    const frac = dotParts[1];
    if (!(frac === '' || allMatch(frac, 0, isDigitOrUnderscore))) return false;
    const segs = dotParts[0].split(':');
    if (segs.length < 2) return false;
    const first = segs[0];
    if (!isDigit(first[0])) return false;
    if (!allMatch(first, 1, isDigitOrUnderscore) && first.length > 1) return false;
    for (let k = 1; k < segs.length; k++) {
      const g = segs[k];
      if (g.length === 1) {
        if (!isDigit(g[0])) return false;
      } else if (g.length === 2) {
        if (!(g[0] >= '0' && g[0] <= '5') || !isDigit(g[1])) return false;
      } else {
        return false;
      }
    }
    return true;
  }
  // leading-dot form: \.[0-9][0-9_]*([eE][-+][0-9]+)?   (no sign!)
  if (v[0] === '.') {
    return matchFloatTail(v.slice(1), true);
  }
  // standard form: [0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
  if (!isDigit(s[0])) return false;
  let i = 1;
  while (i < s.length && isDigitOrUnderscore(s[i])) i++;
  if (s[i] !== '.') return false;
  i++;
  while (i < s.length && isDigitOrUnderscore(s[i])) i++;
  if (i === s.length) return true;
  if (s[i] === 'e' || s[i] === 'E') {
    i++;
    if (s[i] !== '+' && s[i] !== '-') return false;
    i++;
    return allMatch(s, i, isDigit);
  }
  return false;
}

// helper for leading-dot float: digits/underscores then optional exponent.
function matchFloatTail(s, needDigit) {
  if (s === '') return false;
  let i = 0;
  if (!isDigit(s[0])) return false;
  i = 1;
  while (i < s.length && isDigitOrUnderscore(s[i])) i++;
  if (i === s.length) return true;
  if (s[i] === 'e' || s[i] === 'E') {
    i++;
    if (s[i] !== '+' && s[i] !== '-') return false;
    i++;
    return allMatch(s, i, isDigit);
  }
  return false;
}

// timestamp:
//   [0-9]{4}-[0-9]{2}-[0-9]{2}
//   [0-9]{4}-[0-9]{1,2}-[0-9]{1,2}([Tt]|[ \t]+)[0-9]{1,2}:[0-9]{2}:[0-9]{2}
//     (\.[0-9]*)?([ \t]*(Z|[-+][0-9]{1,2}(:[0-9]{2})?))?
export function matchTimestamp(v) {
  const chars = Array.from(v);
  const n = chars.length;
  function digitAt(i) { return i < n && isDigit(chars[i]); }
  // date part: YYYY-
  if (n < 10) return false;
  for (let i = 0; i < 4; i++) if (!digitAt(i)) return false;
  if (chars[4] !== '-') return false;
  let i = 5;
  let mDigits = 0;
  while (i < n && isDigit(chars[i]) && mDigits < 2) { i++; mDigits++; }
  if (mDigits === 0) return false;
  if (i >= n || chars[i] !== '-') return false;
  i++;
  let dDigits = 0;
  while (i < n && isDigit(chars[i]) && dDigits < 2) { i++; dDigits++; }
  if (dDigits === 0) return false;
  if (i === n) {
    // date-only requires exactly 2-digit month and day
    return mDigits === 2 && dDigits === 2;
  }
  // separator: [Tt] or [ \t]+
  if (chars[i] === 'T' || chars[i] === 't') {
    i++;
  } else if (chars[i] === ' ' || chars[i] === '\t') {
    while (i < n && (chars[i] === ' ' || chars[i] === '\t')) i++;
  } else {
    return false;
  }
  // hour: [0-9][0-9]?
  if (!digitAt(i)) return false;
  i++;
  if (digitAt(i)) i++;
  if (i >= n || chars[i] !== ':') return false;
  i++;
  // minute: [0-9][0-9]
  if (!digitAt(i) || !digitAt(i + 1)) return false;
  i += 2;
  if (i >= n || chars[i] !== ':') return false;
  i++;
  // second: [0-9][0-9]
  if (!digitAt(i) || !digitAt(i + 1)) return false;
  i += 2;
  // fraction: (\.[0-9]*)?
  if (i < n && chars[i] === '.') {
    i++;
    while (i < n && isDigit(chars[i])) i++;
  }
  // timezone: ([ \t]*(Z|[-+][0-9][0-9]?(:[0-9][0-9])?))?
  if (i === n) return true;
  while (i < n && (chars[i] === ' ' || chars[i] === '\t')) i++;
  if (i === n) return true;
  if (chars[i] === 'Z') {
    i++;
    return i === n;
  }
  if (chars[i] === '+' || chars[i] === '-') {
    i++;
    if (!digitAt(i)) return false;
    i++;
    if (digitAt(i)) i++;
    if (i < n && chars[i] === ':') {
      i++;
      if (!digitAt(i) || !digitAt(i + 1)) return false;
      i += 2;
    }
    return i === n;
  }
  return false;
}

// Resolve a plain (implicit) scalar's tag, mirroring PyYAML SafeLoader.
export function resolvePlainScalar(value) {
  if (value === '') return TAG_NULL;
  const first = value[0];
  switch (first) {
    case '~': case 'n': case 'N':
      if (matchNull(value)) return TAG_NULL;
      break;
    case 'y': case 'Y': case 't': case 'T': case 'f': case 'F': case 'o': case 'O':
      if (matchBool(value)) return TAG_BOOL;
      break;
    case '<':
      if (value === '<<') return TAG_MERGE;
      break;
    case '=':
      if (value === '=') return TAG_VALUE;
      break;
    case '-': case '+': case '.':
      if (matchFloat(value)) return TAG_FLOAT;
      if (matchInt(value)) return TAG_INT;
      break;
    default:
      if (isDigit(first)) {
        if (matchTimestamp(value)) return TAG_TIMESTAMP;
        if (matchInt(value)) return TAG_INT;
        if (matchFloat(value)) return TAG_FLOAT;
      }
  }
  return TAG_STR;
}

// PyYAML Resolver.resolve for the two implicit flag combinations.
export function resolveScalar(value, implicit) {
  if (implicit[0]) {
    return resolvePlainScalar(value);
  }
  return TAG_STR;
}

// Exported matchers used by the constructor.
export { matchNull, matchBool, matchInt, matchFloat };
